-- Read-only sufficient statistics for OLS training; exact-time LuhaMet pairs.
WITH eligible AS (SELECT a.dateTime,a.outTemp AS y,r.temperature_c AS ref,CASE WHEN r.temperature_c=0 AND a.outTemp>=20 THEN 1 ELSE 0 END AS suspect_zero_hot,1 AS x0,r.temperature_c AS x1,SIN(2*PI()*MOD(a.dateTime,86400)/86400) AS x2,COS(2*PI()*MOD(a.dateTime,86400)/86400) AS x3,SIN(2*PI()*(CASE WHEN a.dateTime<1451606400 THEN a.dateTime-1420070400 WHEN a.dateTime<1483228800 THEN a.dateTime-1451606400 ELSE a.dateTime-1483228800 END)/(CASE WHEN a.dateTime>=1451606400 AND a.dateTime<1483228800 THEN 31622400 ELSE 31536000 END)) AS x4,COS(2*PI()*(CASE WHEN a.dateTime<1451606400 THEN a.dateTime-1420070400 WHEN a.dateTime<1483228800 THEN a.dateTime-1451606400 ELSE a.dateTime-1483228800 END)/(CASE WHEN a.dateTime>=1451606400 AND a.dateTime<1483228800 THEN 31622400 ELSE 31536000 END)) AS x5 FROM loucka_reconstruction.archive a JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=a.dateTime WHERE a.dateTime>=1420070400 AND a.dateTime<1514764800 AND a.outTemp IS NOT NULL AND r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp')) SELECT COUNT(*) AS pairs_base,SUM(suspect_zero_hot) AS flagged_zero_hot_base,SUM(suspect_zero_hot=0) AS pairs_sensitivity,SUM(x0*x0) AS b_s00,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x0 ELSE 0 END) AS f_s00,SUM(x0*x1) AS b_s01,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x1 ELSE 0 END) AS f_s01,SUM(x0*x2) AS b_s02,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x2 ELSE 0 END) AS f_s02,SUM(x0*x3) AS b_s03,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x3 ELSE 0 END) AS f_s03,SUM(x0*x4) AS b_s04,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x4 ELSE 0 END) AS f_s04,SUM(x0*x5) AS b_s05,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*x5 ELSE 0 END) AS f_s05,SUM(x1*x1) AS b_s11,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*x1 ELSE 0 END) AS f_s11,SUM(x1*x2) AS b_s12,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*x2 ELSE 0 END) AS f_s12,SUM(x1*x3) AS b_s13,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*x3 ELSE 0 END) AS f_s13,SUM(x1*x4) AS b_s14,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*x4 ELSE 0 END) AS f_s14,SUM(x1*x5) AS b_s15,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*x5 ELSE 0 END) AS f_s15,SUM(x2*x2) AS b_s22,SUM(CASE WHEN suspect_zero_hot=0 THEN x2*x2 ELSE 0 END) AS f_s22,SUM(x2*x3) AS b_s23,SUM(CASE WHEN suspect_zero_hot=0 THEN x2*x3 ELSE 0 END) AS f_s23,SUM(x2*x4) AS b_s24,SUM(CASE WHEN suspect_zero_hot=0 THEN x2*x4 ELSE 0 END) AS f_s24,SUM(x2*x5) AS b_s25,SUM(CASE WHEN suspect_zero_hot=0 THEN x2*x5 ELSE 0 END) AS f_s25,SUM(x3*x3) AS b_s33,SUM(CASE WHEN suspect_zero_hot=0 THEN x3*x3 ELSE 0 END) AS f_s33,SUM(x3*x4) AS b_s34,SUM(CASE WHEN suspect_zero_hot=0 THEN x3*x4 ELSE 0 END) AS f_s34,SUM(x3*x5) AS b_s35,SUM(CASE WHEN suspect_zero_hot=0 THEN x3*x5 ELSE 0 END) AS f_s35,SUM(x4*x4) AS b_s44,SUM(CASE WHEN suspect_zero_hot=0 THEN x4*x4 ELSE 0 END) AS f_s44,SUM(x4*x5) AS b_s45,SUM(CASE WHEN suspect_zero_hot=0 THEN x4*x5 ELSE 0 END) AS f_s45,SUM(x5*x5) AS b_s55,SUM(CASE WHEN suspect_zero_hot=0 THEN x5*x5 ELSE 0 END) AS f_s55,SUM(x0*y) AS b_t0,SUM(CASE WHEN suspect_zero_hot=0 THEN x0*y ELSE 0 END) AS f_t0,SUM(x1*y) AS b_t1,SUM(CASE WHEN suspect_zero_hot=0 THEN x1*y ELSE 0 END) AS f_t1,SUM(x2*y) AS b_t2,SUM(CASE WHEN suspect_zero_hot=0 THEN x2*y ELSE 0 END) AS f_t2,SUM(x3*y) AS b_t3,SUM(CASE WHEN suspect_zero_hot=0 THEN x3*y ELSE 0 END) AS f_t3,SUM(x4*y) AS b_t4,SUM(CASE WHEN suspect_zero_hot=0 THEN x4*y ELSE 0 END) AS f_t4,SUM(x5*y) AS b_t5,SUM(CASE WHEN suspect_zero_hot=0 THEN x5*y ELSE 0 END) AS f_t5,SUM(y*y) AS b_y2,SUM(CASE WHEN suspect_zero_hot=0 THEN y*y ELSE 0 END) AS f_y2 FROM eligible;
